from __future__ import annotations

from dataclasses import dataclass, asdict, fields
from typing import Any, Optional


@dataclass
class Product:
    sku: str
    name: str
    unit_cost: float
    reorder_point: int

    def to_dict(self) -> dict[str, Any]:
        return asdict(self)

    @classmethod
    def from_dict(cls, d: dict[str, Any]) -> "Product":
        names = {f.name for f in fields(cls)}
        missing = names - set(d)
        if missing:
            raise KeyError(f"Product missing fields: {sorted(missing)}")
        return cls(
            sku=str(d["sku"]),
            name=str(d["name"]),
            unit_cost=float(d["unit_cost"]),
            reorder_point=int(d["reorder_point"]),
        )


@dataclass
class Location:
    code: str
    capacity: int

    def to_dict(self) -> dict[str, Any]:
        return asdict(self)

    @classmethod
    def from_dict(cls, d: dict[str, Any]) -> "Location":
        names = {f.name for f in fields(cls)}
        missing = names - set(d)
        if missing:
            raise KeyError(f"Location missing fields: {sorted(missing)}")
        return cls(code=str(d["code"]), capacity=int(d["capacity"]))


@dataclass
class StockLevel:
    sku: str
    location_code: str
    quantity: int

    def to_dict(self) -> dict[str, Any]:
        return asdict(self)

    @classmethod
    def from_dict(cls, d: dict[str, Any]) -> "StockLevel":
        names = {f.name for f in fields(cls)}
        missing = names - set(d)
        if missing:
            raise KeyError(f"StockLevel missing fields: {sorted(missing)}")
        return cls(
            sku=str(d["sku"]),
            location_code=str(d["location_code"]),
            quantity=int(d["quantity"]),
        )


@dataclass
class Movement:
    kind: str  # 'receive' | 'ship' | 'transfer' | 'adjust'
    sku: str
    qty: int
    src: Optional[str]
    dst: Optional[str]
    ts: int
    ref: str

    VALID_KINDS = ("receive", "ship", "transfer", "adjust")

    def to_dict(self) -> dict[str, Any]:
        return asdict(self)

    @classmethod
    def from_dict(cls, d: dict[str, Any]) -> "Movement":
        names = {f.name for f in fields(cls) if f.name != "VALID_KINDS"}
        missing = names - set(d)
        if missing:
            raise KeyError(f"Movement missing fields: {sorted(missing)}")
        if d["kind"] not in cls.VALID_KINDS:
            raise KeyError(f"Invalid movement kind: {d['kind']!r}")
        return cls(
            kind=str(d["kind"]),
            sku=str(d["sku"]),
            qty=int(d["qty"]),
            src=None if d["src"] is None else str(d["src"]),
            dst=None if d["dst"] is None else str(d["dst"]),
            ts=int(d["ts"]),
            ref=str(d["ref"]),
        )
