```python
from __future__ import annotations

import json
import os
import tempfile
from typing import Any

from models import Movement, Location, Product, StockLevel

_EMPTY: dict[str, list[dict[str, Any]]] = {
    "products": [],
    "locations": [],
    "stock": [],
    "movements": [],
}


class JsonStore:
    """Persistence layer for the warehouse inventory system.

    On-disk format (exactly):
        {"products": [Product.to_dict(), ...],
         "locations": [Location.to_dict(), ...],
         "stock": [StockLevel.to_dict(), ...],
         "movements": [Movement.to_dict(), ...]}
    """

    def __init__(self, path: str) -> None:
        self.path = path

    # ------------------------------------------------------------------ I/O
    def load(self) -> dict[str, list[dict[str, Any]]]:
        """Load the JSON file, returning the raw dict-of-lists structure."""
        try:
            with open(self.path, "r", encoding="utf-8") as f:
                data = json.load(f)
        except FileNotFoundError:
            return {k: list(v) for k, v in _EMPTY.items()}

        if not isinstance(data, dict):
            raise ValueError(f"Corrupt store file {self.path!r}: top level is not an object")

        result: dict[str, list[dict[str, Any]]] = {}
        for key in ("products", "locations", "stock", "movements"):
            value = data.get(key, [])
            if not isinstance(value, list):
                raise ValueError(f"Corrupt store file {self.path!r}: {key!r} is not a list")
            result[key] = value
        return result

    def save(self, data: dict[str, list[dict[str, Any]]]) -> None:
        """Atomically persist the dict-of-lists structure (temp file + os.replace)."""
        ordered = {
            "products": data.get("products", []),
            "locations": data.get("locations", []),
            "stock": data.get("stock", []),
            "movements": data.get("movements", []),
        }
        directory = os.path.dirname(os.path.abspath(self.path))
        os.makedirs(directory, exist_ok=True)
        fd, tmp_path = tempfile.mkstemp(prefix=".warehouse-", suffix=".tmp", dir=directory)
        try:
            with os.fdopen(fd, "w", encoding="utf-8") as f:
                json.dump(ordered, f, indent=2)
                f.flush()
                os.fsync(f.fileno())
            os.replace(tmp_path, self.path)
        except BaseException:
            try:
                os.unlink(tmp_path)
            except OSError:
                pass
            raise

    # ---------------------------------------------------------- typed views
    def _typed(self) -> tuple[dict[str, Product], dict[str, Location],
                             list[StockLevel], list[Movement]]:
        raw = self.load()
        products = {p["sku"]: Product.from_dict(p) for p in raw["products"]}
        locations = {l["code"]: Location.from_dict(l) for l in raw["locations"]}
        stock = [StockLevel.from_dict(s) for s in raw["stock"]]
        movements = [Movement.from_dict(m) for m in raw["movements"]]
        return products, locations, stock, movements

    # ------------------------------------------------------------- lookups
    def get_product(self, sku: str) -> Product:
        products, _, _, _ = self._typed()
        if sku not in products:
            raise KeyError(f"unknown sku: {sku!r}")
        return products[sku]

    def get_location(self, code: str) -> Location:
        _, locations, _, _ = self._typed()
        if code not in locations:
            raise KeyError(f"unknown location: {code!r}")
        return locations[code]

    def stock_at(self, sku: str, code: str) -> int:
        """Current quantity of `sku` at location `code` (0 if no record)."""
        self.get_product(sku)   # raises KeyError for unknown sku
        self.get_location(code)  # raises KeyError for unknown location
        _, _, stock, _ = self._typed()
        for level in stock:
            if level.sku == sku and level.location_code == code:
                return level.quantity
        return 0

    def set_stock(self, sku: str, code: str, qty: int) -> None:
        """Set the quantity of `sku` at `code`; creates the record if needed."""
        self.get_product(sku)
        self.get_location(code)
        raw = self.load()
        for level_dict in raw["stock"]:
            if level_dict["sku"] == sku and level_dict["location_code"] == code:
                level_dict["quantity"] = int(qty)
                self.save(raw)
                return
        raw["stock"].append(StockLevel(sku=sku, location_code=code, quantity=int(qty)).to_dict())
        self.save(raw)

    def append_movement(self, m: Movement) -> None:
        raw = self.load()
        raw["movements"].append(m.to_dict())
        self.save(raw)
