### rules.py
```python
from __future__ import annotations

from typing import Optional

from models import Movement, Product
from storage import JsonStore


class InsufficientStock(Exception):
    """Shipping/transferring more than is on hand at the source."""


class CapacityExceeded(Exception):
    """Receiving/transferring would exceed the destination's capacity."""


class DuplicateRef(Exception):
    """A movement reference already exists in the ledger."""


class Inventory:
    """Business rules layered on top of a JsonStore.

    Rules:
      * qty must be > 0 (ValueError otherwise).
      * ship/transfer cannot take more than is on hand at src (InsufficientStock).
      * receive/transfer cannot push the destination location's total stock
        (summed over all skus) above Location.capacity (CapacityExceeded).
      * every successful call appends exactly one Movement and persists.
      * ref must be unique across all movements (DuplicateRef, changes nothing).
    """

    def __init__(self, store: JsonStore) -> None:
        self.store = store

    # ------------------------------------------------------------ helpers
    def _validate_qty(self, qty: int) -> int:
        if not isinstance(qty, int) or qty <= 0:
            raise ValueError(f"qty must be a positive integer, got {qty!r}")
        return qty

    def _check_ref(self, ref: str) -> None:
        for m in self.store.load()["movements"]:
            if m["ref"] == ref:
                raise DuplicateRef(f"movement ref already used: {ref!r}")

    def _used_capacity(self, code: str) -> int:
        """Total units of all skus currently stored at location `code`."""
        self.store.get_location(code)  # raises KeyError if unknown
        total = 0
        for level in self.store.load()["stock"]:
            if level["location_code"] == code:
                total += int(level["quantity"])
        return total

    def _record(self, kind: str, sku: str, qty: int,
                src: Optional[str], dst: Optional[str], ref: str) -> Movement:
        movement = Movement(
            kind=kind,
            sku=sku,
            qty=qty,
            src=src,
            dst=dst,
            ts=self._next_ts(),
            ref=ref,
        )
        self.store.append_movement(movement)
        return movement

    def _next_ts(self) -> int:
        movements = self.store.load()["movements"]
        if not movements:
            return 1
        return max(int(m["ts"]) for m in movements) + 1

    # ----------------------------------------------------------- operations
    def receive(self, sku: str, qty: int, dst: str, ref: str) -> Movement:
        self._validate_qty(qty)
        self._check_ref(ref)
        product = self.store.get_product(sku)     # KeyError if unknown
        location = self.store.get_location(dst)   # KeyError if unknown

        projected = self._used_capacity(dst) + qty
        if projected > location.capacity:
            raise CapacityExceeded(
                f"receiving {qty} of {sku!r} into {dst!r} would exceed capacity "
                f"({location.capacity}): projected total {projected}"
            )

        new_qty = self.store.stock_at(sku, dst) + qty
        self.store.set_stock(sku, dst, new_qty)
        return self._record("receive", sku, qty, None, dst, ref)

    def ship(self, sku: str, qty: int, src: str, ref: str) -> Movement:
        self._validate_qty(qty)
        self._check_ref(ref)
        self.store.get_product(sku)
        self.store.get_location(src)

        on_hand = self.store.stock_at(sku, src)
        if qty > on_hand:
            raise InsufficientStock(
                f"cannot ship {qty} of {sku!r} from {src!r}: only {on_hand} on hand"
            )

        self.store.set_stock(sku, src, on_hand - qty)
        return self._record("ship", sku, qty, src, None, ref)

    def transfer(self, sku: str, qty: int, src: str, dst: str, ref: str) -> Movement:
        self._validate_qty(qty)
        self._check_ref(ref)
        self.store.get_product(sku)
        self.store.get_location(src)
        self.store.get_location(dst)

        on_hand = self.store.stock_at(sku, src)
        if qty > on_hand:
            raise InsufficientStock(
                f"cannot transfer {qty} of {sku!r} from {src!r}: only {on_hand} on hand"
            )

        # Capacity check on the destination. When src == dst the stock is
        # merely "moved in place", so net change is zero and capacity is safe
        # as long as it already held (it does, since qty <= on_hand there).
        if dst != src:
            projected = self._used_capacity(dst) + qty
            location = self.store.get_location(dst)
            if projected > location.capacity:
                raise CapacityExceeded(
                    f"transferring {qty} of {sku!r} into {dst!r} would exceed capacity "
                    f"({location.capacity}): projected total {projected}"
                )

        self.store.set_stock(sku, src, on_hand - qty)
        if dst != src:
            self.store.set_stock(sku, dst, self.store.stock_at(sku, dst) + qty)
        return self._record("transfer", sku, qty, src, dst, ref)

    def adjust(self, sku: str, qty_delta: int, loc: str, ref: str) -> Movement:
        # adjust takes a signed delta; zero is meaningful (no-op correction),
        # but it still must be an integer and the ref rules still apply.
        if not isinstance(qty_delta, int) or qty_delta == 0:
            raise ValueError(f"qty_delta must be a non-zero integer, got {qty_delta!r}")
        self._check_ref(ref)
        self.store.get_product(sku)
        self.store.get_location(loc)

        if qty_delta > 0:
            location = self.store.get_location(loc)
            projected = self._used_capacity(loc) + qty_delta
            if projected > location.capacity:
                raise CapacityExceeded(
                    f"adjusting +{qty_delta} of {sku!r} at {loc!r} would exceed capacity "
                    f"({location.capacity}): projected total {projected}"
                )
        else:
            on_hand = self.store.stock_at(sku, loc)
            if -qty_delta > on_hand:
                raise InsufficientStock(
                    f"cannot adjust by {qty_delta} of {sku!r} at {loc!r}: "
                    f"only {on_hand} on hand"
                )

        new_qty = self.store.stock_at(sku, loc) + qty_delta
        self.store.set_stock(sku, loc, new_qty)
        return self._record("adjust", sku, qty_delta, loc, None, ref)

    # ------------------------------------------------------------- reports
    def total_on_hand(self, sku: str) -> int:
        self.store.get_product(sku)  # KeyError if unknown
        total = 0
        for level in self.store.load()["stock"]:
            if level["sku"] == sku:
                total += int(level["quantity"])
        return total

    def below_reorder(self) -> list[str]:
        products, _, stock, _ = self._typed_views()
        totals: dict[str, int] = {}
        for level in stock:
            totals[level.sku] = totals.get(level.sku, 0) + level.quantity
        return [
            p.sku for p in products.values()
            if totals.get(p.sku, 0) < p.reorder_point
        ]

    def valuation(self) -> float:
        products, _, stock, _ = self._typed_views()
        costs = {p.sku: p.unit_cost for p in products.values()}
        return float(sum(level.quantity * costs.get(level.sku, 0.0) for level in stock))

    def total_units(self) -> int:
        _, _, stock, _ = self._typed_views()
        return sum(level.quantity for level in stock)

    def ledger(self, sku: str) -> list[Movement]:
        self.store.get_product(sku)  # KeyError if unknown
        movements = [Movement.from_dict(m) for m in self.store.load()["movements"]]
        return sorted((m for m in movements if m.sku == sku), key=lambda m: m.ts)

    def _typed_views(self):
        raw = self.store.load()
        from models import Location, StockLevel
        products = [Product.from_dict(p) for p in raw["products"]]
        locations = [Location.from_dict(l) for l in raw["locations"]]
        stock = [StockLevel.from_dict(s) for s in raw["stock"]]
        return products, locations, stock, None
