```python
from __future__ import annotations

import argparse
import json
import sys

from rules import Inventory
from storage import JsonStore


def _build_parser() -> argparse.ArgumentParser:
    parser = argparse.ArgumentParser(prog="warehouse", description="Warehouse inventory CLI")
    parser.add_argument("--db", required=True, help="path to the JSON store file")

    sub = parser.add_subparsers(dest="command", required=True)

    p_recv = sub.add_parser("receive", help="receive qty of sku into dst")
    p_recv.add_argument("sku")
    p_recv.add_argument("qty", type=int)
    p_recv.add_argument("dst")
    p_recv.add_argument("--ref", required=True)

    p_ship = sub.add_parser("ship", help="ship qty of sku from src")
    p_ship.add_argument("sku")
    p_ship.add_argument("qty", type=int)
    p_ship.add_argument("src")
    p_ship.add_argument("--ref", required=True)

    p_tr = sub.add_parser("transfer", help="transfer qty of sku from src to dst")
    p_tr.add_argument("sku")
    p_tr.add_argument("qty", type=int)
    p_tr.add_argument("src")
    p_tr.add_argument("dst")
    p_tr.add_argument("--ref", required=True)

    p_adj = sub.add_parser("adjust", help="adjust stock of sku at loc by signed delta")
    p_adj.add_argument("sku")
    p_adj.add_argument("qty_delta", type=int)
    p_adj.add_argument("loc")
    p_adj.add_argument("--ref", required=True)

    sub.add_parser("report", help="print valuation, below_reorder and total_units")

    return parser


def _run(args: argparse.Namespace) -> dict:
    store = JsonStore(args.db)
    inv = Inventory(store)

    if args.command == "receive":
        m = inv.receive(args.sku, args.qty, args.dst, args.ref)
        return {"ok": True, "movement": m.to_dict()}

    if args.command == "ship":
        m = inv.ship(args.sku, args.qty, args.src, args.ref)
        return {"ok": True, "movement": m.to_dict()}

    if args.command == "transfer":
        m = inv.transfer(args.sku, args.qty, args.src, args.dst, args.ref)
        return {"ok": True, "movement": m.to_dict()}

    if args.command == "adjust":
        m = inv.adjust(args.sku, args.qty_delta, args.loc, args.ref)
        return {"ok": True, "movement": m.to_dict()}

    if args.command == "report":
        return {
            "valuation": inv.valuation(),
            "below_reorder": inv.below_reorder(),
            "total_units": inv.total_units(),
        }

    raise AssertionError(f"unhandled command: {args.command}")  # pragma: no cover


def main(argv: list[str] | None = None) -> int:
    parser = _build_parser()
    args = parser.parse_args(argv)
    try:
        result = _run(args)
    except (ValueError, KeyError) as exc:
        print(json.dumps({"ok": False, "error": str(exc)}))
        return 1
    except Exception as exc:  # InsufficientStock, CapacityExceeded, DuplicateRef
        print(json.dumps({"ok": False, "error": str(exc), "error_type": type(exc).__name__}))
        return 2
    print(json.dumps(result))
    return 0


if __name__ == "__main__":
    sys.exit(main())
