from __future__ import annotations

import json
import os
import subprocess
import sys
import tempfile
import unittest

from models import Movement
from rules import (
    CapacityExceeded,
    DuplicateRef,
    InsufficientStock,
    Inventory,
)
from storage import JsonStore


def _seed_data() -> dict:
    return {
        "products": [
            {"sku": "SKU-1", "name": "Widget", "unit_cost": 2.5, "reorder_point": 10},
            {"sku": "SKU-2", "name": "Gadget", "unit_cost": 4.0, "reorder_point": 5},
            {"sku": "SKU-3", "name": "Doohickey", "unit_cost": 1.0, "reorder_point": 0},
        ],
        "locations": [
            {"code": "A", "capacity": 100},
            {"code": "B", "capacity": 20},
            {"code": "C", "capacity": 3},
        ],
        "stock": [
            {"sku": "SKU-1", "location_code": "A", "quantity": 50},
            {"sku": "SKU-2", "location_code": "B", "quantity": 8},
        ],
        "movements": [],
    }


class WarehouseTestBase(unittest.TestCase):
    def setUp(self) -> None:
        self.tmpdir = tempfile.TemporaryDirectory()
        self.addCleanup(self.tmpdir.cleanup)
        self.db_path = os.path.join(self.tmpdir.name, "db.json")
        with open(self.db_path, "w", encoding="utf-8") as f:
            json.dump(_seed_data(), f)
        self.store = JsonStore(self.db_path)
        self.inv = Inventory(self.store)


class TestStorage(WarehouseTestBase):
    def test_load_returns_exact_format(self):
        data = self.store.load()
        self.assertEqual(set(data.keys()),
                         {"products", "locations", "stock", "movements"})
        self.assertIsInstance(data["products"], list)
        self.assertIsInstance(data["locations"], list)
        self.assertIsInstance(data["stock"], list)
        self.assertIsInstance(data["movements"], list)
        self.assertEqual(data["stock"][0]["sku"], "SKU-1")

    def test_load_missing_file_returns_empty_structure(self):
        store = JsonStore(os.path.join(self.tmpdir.name, "nope.json"))
        data = store.load()
        self.assertEqual(data, {"products": [], "locations": [],
                                "stock": [], "movements": []})

    def test_get_product_and_location(self):
        p = self.store.get_product("SKU-2")
        self.assertEqual(p.name, "Gadget")
        self.assertEqual(p.unit_cost, 4.0)
        loc = self.store.get_location("B")
        self.assertEqual(loc.capacity, 20)

    def test_get_unknown_sku_raises_keyerror(self):
        with self.assertRaises(KeyError):
            self.store.get_product("NOPE")

    def test_get_unknown_location_raises_keyerror(self):
        with self.assertRaises(KeyError):
            self.store.get_location("ZZ")

    def test_stock_at_defaults_to_zero(self):
        self.assertEqual(self.store.stock_at("SKU-3", "A"), 0)

    def test_stock_at_unknown_sku_or_location_raises(self):
        with self.assertRaises(KeyError):
            self.store.stock_at("NOPE", "A")
        with self.assertRaises(KeyError):
            self.store.stock_at("SKU-1", "ZZ")

    def test_set_stock_creates_and_updates(self):
        self.store.set_stock("SKU-3", "C", 2)
        self.assertEqual(self.store.stock_at("SKU-3", "C"), 2)
        self.store.set_stock("SKU-3", "C", 1)
        self.assertEqual(self.store.stock_at("SKU-3", "C"), 1)
        # on-disk format still valid after save
        with open(self.db_path, encoding="utf-8") as f:
            on_disk = json.load(f)
        self.assertEqual(on_disk["stock"][-1]["sku"], "SKU-3")

    def test_set_stock_unknown_refs_raise_and_do_not_write(self):
        before = self.store.load()
        with self.assertRaises(KeyError):
            self.store.set_stock("NOPE", "A", 5)
        with self.assertRaises(KeyError):
            self.store.set_stock("SKU-1", "ZZ", 5)
        self.assertEqual(self.store.load(), before)

    def test_append_movement_persists(self):
        m = Movement(kind="receive", sku="SKU-1", qty=5, src=None, dst="A",
                     ts=1, ref="R1")
        self.store.append_movement(m)
        data = self.store.load()
        self.assertEqual(len(data["movements"]), 1)
        self.assertEqual(data["movements"][0]["ref"], "R1")


class TestRulesQtyAndRef(WarehouseTestBase):
    def test_receive_zero_qty_raises_valueerror(self):
        with self.assertRaises(ValueError):
            self.inv.receive("SKU-1", 0, "A", "r-zero")

    def test_receive_negative_qty_raises_valueerror(self):
        with self.assertRaises(ValueError):
            self.inv.receive("SKU-1", -3, "A", "r-neg")

    def test_ship_zero_qty_raises_valueerror(self):
        with self.assertRaises(ValueError):
            self.inv.ship("SKU-1", 0, "A", "s-zero")

    def test_transfer_zero_qty_raises_valueerror(self):
        with self.assertRaises(ValueError):
            self.inv.transfer("SKU-1", 0, "A", "B", "t-zero")

    def test_adjust_zero_delta_raises_valueerror(self):
        with self.assertRaises(ValueError):
            self.inv.adjust("SKU-1", 0, "A", "a-zero")

    def test_duplicate_ref_receive_changes_nothing(self):
        self.inv.receive("SKU-1", 5, "A", "dup")
        before = self.store.load()
        with self.assertRaises(DuplicateRef):
            self.inv.receive("SKU-1", 5, "A", "dup")
        self.assertEqual(self.store.load(), before)

    def test_duplicate_ref_ship_changes_nothing(self):
        self.inv.ship("SKU-1", 5, "A", "dup")
