class TestCli(unittest.TestCase):
    def setUp(self) -> None:
        self.tmpdir = tempfile.TemporaryDirectory()
        self.addCleanup(self.tmpdir.cleanup)
        self.db_path = os.path.join(self.tmpdir.name, "cli.json")
        with open(self.db_path, "w", encoding="utf-8") as f:
            json.dump(_seed_data(), f)

    def _run_cli(self, *args: str) -> tuple[int, dict]:
        proc = subprocess.run(
            [sys.executable, "-m", "cli", "--db", self.db_path, *args],
            capture_output=True, text=True,
            cwd=os.path.dirname(os.path.abspath(__file__)) or ".",
        )
        lines = [ln for ln in proc.stdout.strip().splitlines() if ln.strip()]
        payload = json.loads(lines[-1]) if lines else {}
        return proc.returncode, payload

    def test_cli_receive_prints_json_line(self):
        code, payload = self._run_cli("receive", "SKU-3", "4", "C", "--ref", "c1")
        self.assertEqual(code, 0)
        self.assertTrue(payload["ok"])
        self.assertEqual(payload["movement"]["kind"], "receive")

    def test_cli_ship_insufficient_returns_error_json(self):
        code, payload = self._run_cli("ship", "SKU-2", "99", "B", "--ref", "c2")
        self.assertEqual(code, 2)
        self.assertFalse(payload["ok"])
        self.assertEqual(payload["error_type"], "InsufficientStock")

    def test_cli_report(self):
        code, payload = self._run_cli("report")
        self.assertEqual(code, 0)
        self.assertAlmostEqual(payload["valuation"], 157.0)
        self.assertEqual(payload["below_reorder"], [])
        self.assertEqual(payload["total_units"], 58)

    def test_cli_transfer(self):
        code, payload = self._run_cli("transfer", "SKU-1", "10", "A", "B", "--ref", "c3")
        self.assertEqual(code, 0)
        self.assertEqual(payload["movement"]["dst"], "B")
        with open(self.db_path, encoding="utf-8") as f:
            stock = json.load(f)["stock"]
        at_b = [s for s in stock if s["sku"] == "SKU-1" and s["location_code"] == "B"]
        self.assertEqual(at_b[0]["quantity"], 10)


